# Mock OAuth 2.0 authorization-code-with-PKCE flow (illustrative only).
import hashlib, base64, secrets, time, json

# --- authorization server state ---
CLIENTS = {
    "client-123": {
        "name": "Calendar Sync",
        "redirect_uris": ["https://app.example.com/callback"],
        "client_secret": "super-secret",          # confidential client
        "allowed_scopes": {"calendar.read", "calendar.write", "openid"},
    },
}
AUTH_CODES = {}      # code -> {client_id, scope, redirect_uri, challenge, user, exp}
ACCESS_TOKENS = {}   # jti -> {user, scope, client_id, exp}
REFRESH_TOKENS = {}  # token -> {user, scope, client_id, rotated_from}

def make_pkce_pair():
    """RFC 7636: verifier (43-128 chars) + S256 challenge."""
    verifier = base64.urlsafe_b64encode(secrets.token_bytes(32)).rstrip(b"=").decode()
    challenge = base64.urlsafe_b64encode(
        hashlib.sha256(verifier.encode()).digest()
    ).rstrip(b"=").decode()
    return verifier, challenge

def authorize(client_id, redirect_uri, scope, state, code_challenge, user):
    """Step 1-3: user logs in + approves; server mints auth code."""
    c = CLIENTS.get(client_id)
    if not c or redirect_uri not in c["redirect_uris"]:
        return None, "invalid redirect_uri"
    if not set(scope.split()) <= c["allowed_scopes"]:
        return None, "invalid scope"
    code = secrets.token_urlsafe(24)
    AUTH_CODES[code] = {
        "client_id": client_id, "scope": scope, "redirect_uri": redirect_uri,
        "challenge": code_challenge, "user": user, "exp": time.time() + 600,
    }
    return f"{redirect_uri}?code={code}&state={state}", None

def exchange_code(code, code_verifier, client_id, client_secret=None):
    """Step 4-5: client exchanges code + PKCE verifier for tokens."""
    rec = AUTH_CODES.pop(code, None)
    if not rec or rec["exp"] < time.time():
        return None, "invalid or expired code"
    if rec["client_id"] != client_id:
        return None, "client mismatch"
    # PKCE: hash verifier, compare to stored challenge
    expected = base64.urlsafe_b64encode(
        hashlib.sha256(code_verifier.encode()).digest()
    ).rstrip(b"=").decode()
    if not secrets.compare_digest(expected, rec["challenge"]):
        return None, "PKCE verifier mismatch"
    # confidential client: also check secret
    if client_secret and client_secret != CLIENTS[client_id]["client_secret"]:
        return None, "client secret mismatch"
    # mint access + refresh tokens
    jti = secrets.token_hex(8)
    ACCESS_TOKENS[jti] = {"user": rec["user"], "scope": rec["scope"],
                          "client_id": client_id, "exp": time.time() + 3600}
    rt = secrets.token_urlsafe(32)
    REFRESH_TOKENS[rt] = {"user": rec["user"], "scope": rec["scope"],
                          "client_id": client_id}
    return {"access_token": jti, "expires_in": 3600,
            "refresh_token": rt, "scope": rec["scope"]}, None

def call_api(access_jti, action):
    """Resource server checks token + scope."""
    tok = ACCESS_TOKENS.get(access_jti)
    if not tok or tok["exp"] < time.time():
        return 401, "token invalid"
    if action == "read" and "calendar.read" not in tok["scope"]:
        return 403, "missing scope"
    if action == "write" and "calendar.write" not in tok["scope"]:
        return 403, "missing scope"
    return 200, f"OK for user {tok['user']}"

if __name__ == "__main__":
    verifier, challenge = make_pkce_pair()
    url, err = authorize("client-123", "https://app.example.com/callback",
                         "calendar.read", "xyz-state", challenge, user="alice")
    code = url.split("code=")[1].split("&")[0]
    tokens, err = exchange_code(code, verifier, "client-123", "super-secret")
    print("tokens:", tokens)
    print("read:", call_api(tokens["access_token"], "read"))
    print("write (should fail):", call_api(tokens["access_token"], "write"))
